CREATE TABLE poinsattachdoccontent (
id BIGINT NOT NULL,
data BYTEA,
partInfo BIGINT NOT NULL,
PRIMARY KEY (id, partInfo)
) PARTITION BY LIST (partInfo);

CREATE TABLE poinsattachdoccontent_part_1 PARTITION OF poinsattachdoccontent FOR VALUES IN (1);
CREATE TABLE poinsattachdoccontent_part_2 PARTITION OF poinsattachdoccontent FOR VALUES IN (2);
CREATE TABLE poinsattachdoccontent_part_3 PARTITION OF poinsattachdoccontent FOR VALUES IN (3);
CREATE TABLE poinsattachdoccontent_part_4 PARTITION OF poinsattachdoccontent FOR VALUES IN (4);
CREATE TABLE poinsattachdoccontent_part_5 PARTITION OF poinsattachdoccontent FOR VALUES IN (5);
CREATE TABLE poinsattachdoccontent_part_6 PARTITION OF poinsattachdoccontent FOR VALUES IN (6);
CREATE TABLE poinsattachdoccontent_part_7 PARTITION OF poinsattachdoccontent FOR VALUES IN (7);
CREATE TABLE poinsattachdoccontent_part_8 PARTITION OF poinsattachdoccontent FOR VALUES IN (8);
CREATE TABLE poinsattachdoccontent_part_9 PARTITION OF poinsattachdoccontent FOR VALUES IN (9);
CREATE TABLE poinsattachdoccontent_part_10 PARTITION OF poinsattachdoccontent FOR VALUES IN (10);
CREATE TABLE poinsattachdoccontent_part_11 PARTITION OF poinsattachdoccontent FOR VALUES IN (11);
CREATE TABLE poinsattachdoccontent_part_12 PARTITION OF poinsattachdoccontent FOR VALUES IN (12);

CREATE INDEX INDPOINSattachDocContent ON poinsattachdoccontent (id, partInfo);

